(()=>{
  const handSrc='data:image/webp;base64,';
  const meteorSrc='data:image/webp;base64,';
  const install=()=>{
    const fx=document.getElementById('mq-cinematic-fx');
    if(!fx)return;
    const hand=fx.querySelector('.mq-knife-hand');
    if(hand&&hand.dataset.mqReferenceV5!=='1'){
      hand.innerHTML='<img class="mq-horror-hand-img" alt="" aria-hidden="true">';
      hand.querySelector('img').src=handSrc;
      hand.dataset.mqReferenceV5='1';
    }
    fx.querySelectorAll('.mq-meteor').forEach(m=>{
      if(m.dataset.mqReferenceV5==='1')return;
      m.innerHTML='<img class="mq-meteor-reference" alt="" aria-hidden="true">';
      m.querySelector('img').src=meteorSrc;
      m.dataset.mqReferenceV5='1';
    });
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
